mapper.select:
        SELECT


--         级联表的字段
        ,gongjiaoxianlu.gongjiaoxianlu_name as gongjiaoxianluName
        ,yonghu.yonghu_name as yonghuName
        ,yonghu.yonghu_phone as yonghuPhone

        FROM to_station_remind  a
        left JOIN gongjiaoxianlu gongjiaoxianlu ON a.gongjiaoxianlu_id = gongjiaoxianlu.id
        left JOIN yonghu yonghu ON a.yonghu_id = yonghu.id



                and a.id in

                #{item}



                and (
                    a.yonghu_id = #{params.yonghuId}
                )


                and (
                    a.gongjiaoxianlu_id = #{params.gongjiaoxianluId}
                )


                and a.stop_name like CONCAT('%',#{params.stopName},'%')


                and a.remind_status = #{params.remindStatus}


                and gongjiaoxianlu.gongjiaoxianlu_name like CONCAT('%',#{params.gongjiaoxianluName},'%')



        order by a.${params.orderBy} desc
